escenas.animacion:
const W=A.W, ac=A.accent;
const kC=A.k('congelas',1.0), kP=A.k('playa',2.0), kCh=A.k('Chile,',2.667), kE=A.k('enero?',3.667);
A.bg('#0B1E33','#06121F');
const f=A.p(kC,0.5,'crashIn');
const f2=A.p(kC,0.9,'whip');
// SOL (verano)
const sp=A.pop(0.0,0.5);
A.with(()=>{ A.sun(170,540,70); },{x:170,y:540,scale:sp*(1+0.04*Math.sin(t*4)),rot:t*0.3});
// MAR
const sea=A.p(0.1,0.6,'softLand');
ctx.save();ctx.globalAlpha=sea;
let g=ctx.createLinearGradient(0,760,0,1010);
g.addColorStop(0,'#0E4A6B');g.addColorStop(1,A.lerp(0,1,f)>0.5?'#1E8FA8':'#1A7A96');
ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(0,770);
for(let x=0;x<=W;x+=20)ctx.lineTo(x,770+Math.sin(x*0.02+t*2)*6);
ctx.lineTo(W,1010);ctx.lineTo(0,1010);ctx.closePath();ctx.fill();ctx.restore();
for(let j=0;j<3;j++){const yy=830+j*55;const pts=[];for(let x=0;x<=W;x+=30)pts.push([x,yy+Math.sin(x*0.025+t*2.5+j)*7]);A.line(pts,{stroke:ac,lw:3,alpha:0.35*sea});}
// ARENA
ctx.save();ctx.fillStyle='#E0B66E';ctx.globalAlpha=A.p(0.15,0.6,'softLand');ctx.beginPath();ctx.moveTo(0,1000);
for(let x=0;x<=W;x+=20)ctx.lineTo(x,1000+Math.sin(x*0.015+t*1.5)*8);
ctx.lineTo(W,1120);ctx.lineTo(0,1120);ctx.closePath();ctx.fill();ctx.restore();
A.lib.hatch(ctx,[[0,1030],[W,1030],[W,1120],[0,1120]],{angle:-0.5,spacing:22,width:2,color:'rgba(120,80,30,0.35)'});
// QUITASOL en "playa"
const up=A.pop(kP,0.45);
if(up>0)A.with(()=>{
 A.line([[150,1110],[150,900]],{stroke:'#FFFFFF',lw:6});
 ctx.fillStyle='#FF7043';ctx.beginPath();ctx.moveTo(40,910);ctx.quadraticCurveTo(150,800,260,910);ctx.closePath();ctx.fill();
 ctx.fillStyle='#FFFFFF';ctx.beginPath();ctx.moveTo(120,910);ctx.quadraticCurveTo(150,820,180,910);ctx.closePath();ctx.fill();
},{x:150,y:1110,scale:up});
// BANDERA en "Chile"
const fp=A.pop(kCh,0.45);
if(fp>0)A.with(()=>{
 A.line([[660,1110],[660,950]],{stroke:'#FFFFFF',lw:5});
 const wv=Math.sin(t*6)*4;
 A.rect(662,950+wv*0.3,110,36,{fill:'#FFFFFF'});
 A.rect(662,986+wv*0.3,110,36,{fill:'#D52B1E'});
 A.rect(662,950+wv*0.3,38,36,{fill:'#0039A6'});
 A.circle(681,968+wv*0.3,7,{fill:'#FFFFFF'});
 A.label('CHILE',715,1075,{size:34,bg:'#D52B1E',color:'#FFFFFF'});
},{x:660,y:1110,scale:fp});
// PERSONA
const shiver=f*(1-A.p(kC+0.7,1.3,'softInOut'))*10+f*2.5;
const pIn=A.p(0.2,0.6,'snapSettle');
A.with(()=>{
 A.person(450,1010,{scale:1.6,color:f>0.4?ac:'#FFB74D'});
},{x:450,y:1010,alpha:pIn,shake:shiver});
// agua delante de los tobillos
A.rect(330,985,240,30,{fill:'#1A7A96',alpha:0.75*sea,r:12});
// impacto en "congelas"
A.rings(450,900,kC,{count:3,speed:500,gap:0.12,maxR:380,color:ac,lw:5,alpha:0.8});
A.flash(kC,0.25,0.35);
// escarcha
if(f>0)A.particles(26,7,(i,r)=>{
 const a=r()*Math.PI*2, d=110+r()*190, s=10+r()*14;
 const x=450+Math.cos(a)*d, y=820+Math.sin(a)*d*0.9+((t*30+r()*50)%40);
 const al=f*(0.5+0.5*Math.sin(t*5+i));
 for(let q=0;q<3;q++){const an=q*Math.PI/3+t;A.line([[x-Math.cos(an)*s,y-Math.sin(an)*s],[x+Math.cos(an)*s,y+Math.sin(an)*s]],{stroke:'#E6FBFF',lw:3,alpha:al});}
});
const bp=A.pop(kC+0.15,0.45);
if(bp>0)A.label('¡BRRR!',450,560,{size:64,bg:ac,color:'#06121F',scale:bp});
// TERMÓMETRO
const th=A.p(0.3,0.6,'softLand');
const temp=A.lerp(30,15,f2);
const col=f2>0.5?ac:'#FF5A3C';
A.with(()=>{
 A.rect(855,600,50,440,{r:25,fill:'#0A1A2B',stroke:'#FFFFFF',lw:5});
 const lv=(temp/40)*400;
 A.rect(865,1040-lv,30,lv+10,{r:15,fill:col,glow:20});
 A.circle(880,1065,42,{fill:col,stroke:'#FFFFFF',lw:5,glow:25});
 for(let i=0;i<=4;i++)A.line([[905,1040-i*100],[925,1040-i*100]],{stroke:'#FFFFFF',lw:3,alpha:0.7});
 A.text(A.counter(30,15,f2,0)+'°',880,555,{size:72,color:col,weight:'900',align:'center',stroke:'#06121F',strokeWidth:8});
},{x:880,y:820,alpha:th,scale:0.9+0.1*th,shake:f2>0&&f2<1?6:0});
// escarcha en bordes
if(f>0){ctx.save();const rg=ctx.createRadialGradient(540,860,300,540,860,900);rg.addColorStop(0,'rgba(77,208,225,0)');rg.addColorStop(1,'rgba(200,245,255,'+(0.35*f)+')');ctx.fillStyle=rg;ctx.fillRect(0,400,W,760);ctx.restore();}
// ENERO: calendario + comparación
const cp=A.pop(kE-0.1,0.45);
if(cp>0)A.with(()=>{
 A.rect(420,1350,240,190,{r:22,fill:'#FFFFFF'});
 A.rect(420,1350,240,60,{r:22,fill:'#FF5A3C'});
 A.text('ENERO',540,1392,{size:40,color:'#FFFFFF',weight:'900',align:'center'});
 A.sun(540,1478,30);
},{x:540,y:1445,scale:cp});
const a1=A.pop(kE+0.05,0.4), a2=A.pop(kE+0.2,0.4);
if(a1>0)A.label('AIRE 30°',290,1640,{size:54,bg:'#FF5A3C',color:'#FFFFFF',scale:a1});
if(a2>0)A.label('AGUA 15°',790,1640,{size:54,bg:ac,color:'#06121F',scale:a2});
if(a2>0)A.text('vs',540,1660,{size:44,color:'#FFFFFF',weight:'800',align:'center',alpha:a2});

const W=A.W, ac=A.accent, warm='#FF8A65';
A.bg('#06121f','#0a2238');
const tC=A.k('corriente',1.0), tH=A.k('Humboldt:',1.667), tE=A.k('enorme',2.333), tR=A.k('río',2.667), tF=A.k('fría',3.667), tO=A.k('océano.',4.667);
const cx=y=>720-50*Math.sin((y-420)/700*Math.PI)+14*Math.sin(y/55);
const pMap=A.p(0,0.9,'softLand');
const pO=A.p(tO,0.6,'glide');
const zoom=A.lerp(1,0.9,pO);
A.with(()=>{
  // ocean warm tint (the rest of the ocean)
  if(pO>0){
    const g=ctx.createLinearGradient(0,0,700,0);
    g.addColorStop(0,'rgba(255,138,101,'+(0.28*pO)+')');
    g.addColorStop(1,'rgba(255,138,101,0)');
    ctx.fillStyle=g; ctx.fillRect(-100,400,800,740);
    A.text('OCÉANO PACÍFICO',290,500,{size:42,color:warm,weight:'800',align:'center',alpha:pO});
    A.text('más templado',290,548,{size:30,color:'#FFCCBC',weight:'600',align:'center',alpha:pO*0.9});
  }
  // land
  const land=[];
  for(let y=410;y<=1130;y+=15) land.push([cx(y),y]);
  const poly=land.concat([[1180,1130],[1180,410]]);
  ctx.save(); ctx.globalAlpha=pMap;
  A.lib.inkPath(ctx,poly,{closed:true,fill:'#16304a',color:'rgba(0,0,0,0)',width:1});
  A.lib.hatch(ctx,poly,{angle:0.8,spacing:16,width:1.5,color:'rgba(160,200,230,0.18)'});
  ctx.restore();
  A.line(land,{stroke:'#E8F4FF',lw:5,progress:pMap});
  A.text('CHILE',900,780,{size:46,color:'#E8F4FF',weight:'800',align:'center',alpha:pMap*0.8});
  // current band
  const pC=A.p(tC,1.1,'glide');
  const pE=A.p(tE,0.7,'whip');
  const pR=A.p(tR,0.5,'softInOut');
  const pF=A.p(tF,0.6,'softInOut');
  const w=A.lerp(45,135,pE);
  const headY=1120-700*pC;
  if(pC>0){
    const L=[],R=[];
    for(let y=1125;y>=headY;y-=12){R.push([cx(y)-18,y]);L.push([cx(y)-18-w*(0.6+0.4*Math.min(1,(y-headY)/80)),y]);}
    const band=R.concat(L.reverse());
    ctx.save();
    ctx.globalAlpha=0.22+0.15*pF;
    ctx.fillStyle=ac; ctx.shadowColor=ac; ctx.shadowBlur=30*pF;
    ctx.beginPath(); band.forEach((q,i)=>i?ctx.lineTo(q[0],q[1]):ctx.moveTo(q[0],q[1])); ctx.closePath(); ctx.fill();
    ctx.restore();
    // flowing streaks
    const speed=140+260*pR;
    A.particles(70,7,(i,rnd)=>{
      const off=rnd(), ph=rnd(), sp=0.7+0.6*rnd();
      let y=1120-((ph*700+t*speed*sp)%700);
      if(y<headY+10) return;
      const x=cx(y)-22-off*(w-10);
      const len=22+30*pR;
      A.line([[x,y+len],[x,y]],{stroke:pF>0.5?'#E0F7FA':ac,lw:4,alpha:0.85});
    });
    A.arrow(cx(headY+60)-18-w/2,headY+60,cx(headY)-18-w/2,headY-20,{color:'#E0F7FA',lw:7,head:26,alpha:pC>0.05?1:0});
    A.text('SUR',cx(1080)-18-w/2,1105,{size:26,color:'#B2EBF2',weight:'700',align:'center',alpha:A.p(tC,0.4)});
  }
  // label Humboldt
  const sH=A.pop(tH,0.5);
  if(t>=tH){
    const ly=800, bx=cx(ly)-18-w;
    A.line([[400,ly],[bx,ly]],{stroke:ac,lw:3,progress:A.p(tH,0.4,'glide'),dash:[8,8]});
    A.circle(bx,ly,9,{fill:ac,glow:20,alpha:A.p(tH,0.3)});
    A.label('HUMBOLDT',290,ly,{size:50,bg:ac,color:'#06121f',scale:sH});
    const pr=A.p(tR,0.4,'softLand');
    if(pr>0){
      const s=t>=tF?'= un río frío':'= un río';
      A.text(s,290,ly+80,{size:40,color:t>=tF?ac:'#FFFFFF',weight:'800',align:'center',alpha:pr});
    }
  }
  A.rings(cx(760)-18-w/2,760,tO,{count:3,speed:260,gap:0.25,maxR:300,color:ac,lw:4});
},{x:540,y:770,scale:zoom});
// thermometer secondary zone
const pT=A.p(tF-0.1,0.5,'snapSettle');
if(pT>0){
  const s=A.pop(tF-0.1,0.5);
  A.with(()=>{
    const lvl=A.lerp(0.85,0.22,A.p(tF,1.0,'glide'));
    const top=1380,bot=1640;
    A.rect(510,top,60,bot-top+20,{r:30,fill:'#0d2236',stroke:'#E8F4FF',lw:5});
    const col=lvl>0.5?warm:ac;
    const fh=(bot-top)*lvl;
    A.rect(522,bot-fh,36,fh+20,{r:18,fill:col,glow:20});
    A.circle(540,1680,46,{fill:col,stroke:'#E8F4FF',lw:5,glow:25});
    for(let i=0;i<5;i++) A.line([[575,top+30+i*50],[600,top+30+i*50]],{stroke:'#E8F4FF',lw:3,alpha:0.7});
  },{x:540,y:1560,scale:s});
  A.label('FRÍA',780,1560,{size:60,bg:ac,color:'#06121f',scale:A.pop(tF+0.15,0.45)});
  // frost flakes
  A.particles(14,3,(i,rnd)=>{
    const x=330+rnd()*420, y0=1360+rnd()*80, ph=rnd();
    const y=y0+((t-tF)*90+ph*300)%360;
    const a=A.clamp((t-tF)*3)*0.7;
    if(x>480&&x<620) return;
    A.with(()=>{for(let k=0;k<3;k++){const an=k*Math.PI/3;A.line([[x-9*Math.cos(an),y-9*Math.sin(an)],[x+9*Math.cos(an),y+9*Math.sin(an)]],{stroke:'#E0F7FA',lw:2.5,alpha:a});}},{});
  });
}
A.flash(tF,0.25,0.15);

const W=A.W, ac=A.accent;
const K=(w,d)=>A.k(w,d);
const tSur=K('sur,',1.0), tAguas=K('aguas',1.67), tAnt=K('Antártica,',3.0), tSube=K('sube',3.67), tCosta=K('costa',5.0), tChile=K('Chile',5.67), tPeru=K('Perú.',6.33);
A.bg('#05132a','#0b2d4f',true);
const pal=A.pal||{};
const pale=pal.paleBlue||'#9fd4ff', white=pal.lineWhite||'#f2f6ff';
const coast=[[560,420],[600,520],[640,610],[695,700],[688,820],[678,960],[668,1100],[660,1240],[648,1360],[625,1450],[598,1510],[640,1545]];
const ant=[[290,1775],[400,1715],[500,1675],[548,1630],[585,1615],[612,1650],[650,1700],[800,1715],[960,1700],[1080,1690],[1080,1775]];
const cur=[[560,1640],[515,1520],[565,1380],[585,1240],[595,1100],[605,960],[615,820],[622,710],[560,600],[515,510],[470,420]];
const lens=[0];for(let i=1;i<cur.length;i++){const a=cur[i-1],b=cur[i];lens.push(lens[i-1]+Math.hypot(b[0]-a[0],b[1]-a[1]));}
const L=lens[lens.length-1];
const at=s=>{const d=A.clamp(s)*L;let i=1;while(i<lens.length-1&&lens[i]<d)i++;const a=cur[i-1],b=cur[i];const f=(d-lens[i-1])/(lens[i]-lens[i-1]||1);return [A.lerp(a[0],b[0],f),A.lerp(a[1],b[1],f),Math.atan2(b[1]-a[1],b[0]-a[0])];};
const zoom=A.lerp(1,1.05,A.p(0,A.dur,'cruise'));
A.with(()=>{
  // tierra
  const pDraw=A.p(0,1.3,'softLand');
  const land=coast.concat([[1080,1545],[1080,420]]);
  const la=A.p(0.5,0.8,'softInOut');
  ctx.save();ctx.globalAlpha=la;ctx.fillStyle='#16324f';ctx.beginPath();land.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.fill();ctx.restore();
  if(la>0.01){try{ctx.save();ctx.globalAlpha=la*0.5;A.lib.hatch(ctx,land,{angle:45,spacing:20,width:1.5,color:pale});ctx.restore();}catch(e){}}
  A.line(coast,{stroke:white,lw:5,progress:pDraw});
  // brillo de la costa
  const cg=A.p(tCosta-0.1,0.5,'softLand')*(0.6+0.4*Math.sin(t*8));
  if(t>tCosta-0.1)A.line(coast,{stroke:ac,lw:9,alpha:cg*0.8});
  // Antártica
  const sA=A.pop(tAnt,0.5);
  if(t>tAnt){
    A.with(()=>{
      ctx.save();ctx.fillStyle='#e8f3ff';ctx.beginPath();ant.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();ctx.fill();ctx.restore();
      try{ctx.save();ctx.globalAlpha=0.35;A.lib.hatch(ctx,ant,{angle:-30,spacing:16,width:1.5,color:'#6aa6d8'});ctx.restore();}catch(e){}
      A.line(ant.slice(0,ant.length-1),{stroke:white,lw:4});
    },{x:600,y:1700,scale:sA});
    A.rings(585,1640,tAnt,{count:3,speed:260,gap:60,maxR:260,color:pale,lw:4});
    A.label('ANTÁRTICA',820,1655,{size:46,bg:pale,color:'#05132a',scale:A.pop(tAnt+0.1)});
  }
  A.flash(tAnt,0.25,0.25);
  // agua fría
  if(t>tAguas){
    const ap=A.p(tAguas,0.6,'softLand');
    A.particles(26,7,(i,r)=>{
      const ang=r()*6.28+t*(0.4+r()*0.5), rad=60+r()*190;
      const x=470+Math.cos(ang)*rad*1.2, y=1600+Math.sin(ang)*rad*0.4;
      A.circle(x,y,5+r()*7,{fill:pale,alpha:ap*(t>tSube?A.clamp(1-(t-tSube)/1.2):1)*0.8});
    });
  }
  // flecha SUR
  if(t>tSur-0.1&&t<tSube+0.4){
    const sp=A.p(tSur-0.1,0.6,'whip'), out=1-A.p(tSube,0.4,'accelExit');
    A.arrow(230,900,230,A.lerp(900,1440,sp),{progress:1,color:ac,lw:12,head:34,alpha:out});
    A.text('SUR',230,A.lerp(860,1520,sp),{size:84,color:ac,weight:900,align:'center',alpha:out*A.p(tSur,0.3)});
  }
  // corriente de Humboldt
  if(t>tSube-0.05){
    const pc=A.p(tSube-0.05,2.6,'glide');
    A.line(cur,{stroke:ac,lw:46,alpha:0.22,progress:pc});
    A.line(cur,{stroke:ac,lw:12,alpha:0.95,progress:pc});
    for(let i=0;i<14;i++){
      const s=((i/14)+t*0.18)%1; if(s>pc-0.02)continue;
      const [x,y,a]=at(s);
      A.with(()=>{A.line([[-14,-16],[10,0],[-14,16]],{stroke:'#05132a',lw:6});},{x,y,rot:a});
    }
    for(let i=0;i<8;i++){
      const s=((i/8)+t*0.12+0.05)%1; if(s>pc)continue;
      const [x,y]=at(s);
      A.circle(x-40+Math.sin(t*3+i)*8,y,7,{fill:pale,alpha:0.85});
    }
    const [hx,hy]=at(pc);
    if(pc<1)A.circle(hx,hy,18,{fill:ac,glow:30});
  }
  // etiquetas de país
  if(t>tChile-0.05)A.label('CHILE',860,1000,{size:64,bg:ac,color:'#05132a',scale:A.pop(tChile-0.05)});
  if(t>tPeru-0.05)A.label('PERÚ',860,560,{size:64,bg:ac,color:'#05132a',scale:A.pop(tPeru-0.05)});
},{x:600,y:1080,scale:zoom,shake:(t>tAnt&&t<tAnt+0.25)?6:0});

const W=A.W, acc=A.accent, COLD='#5fd3ff';
const tV=A.k('viento',2), tE=A.k('empuja',2.33), tS=A.k('superficie',4), tM=A.k('mar',4.33);
const tF=A.k('fondo',6), tSu=A.k('sube',6.33), tFr=A.k('fría',7.67), tG=A.k('surgencia',8.67);
A.bg('#06142b','#020812',true);
const SY=600;
const floor=[[0,1110],[300,1100],[560,1060],[720,980],[800,860],[840,720],[870,610],[900,575],[1080,540],[1080,1120],[0,1120]];
const bez=(u)=>{const P=[[140,1065],[620,1065],[815,930],[840,612]];const m=1-u;
return [m*m*m*P[0][0]+3*m*m*u*P[1][0]+3*m*u*u*P[2][0]+u*u*u*P[3][0], m*m*m*P[0][1]+3*m*m*u*P[1][1]+3*m*u*u*P[2][1]+u*u*u*P[3][1]];};
const cam=A.lerp(1,1.05,A.p(0,9.25,'cruise'));
const shk=A.clamp(1-(t-tG)/0.35)*(t>tG?8:0);
A.with(()=>{
 const pin=A.p(0,1.2,'softLand');
 // agua
 ctx.save();ctx.globalAlpha=pin;
 const g=ctx.createLinearGradient(0,SY,0,1120);g.addColorStop(0,'#1d5f9a');g.addColorStop(1,'#08223f');
 ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(0,SY);
 for(let x=0;x<=900;x+=20)ctx.lineTo(x,SY+6*Math.sin(x*0.02+t*3));
 ctx.lineTo(900,1120);ctx.lineTo(0,1120);ctx.closePath();ctx.fill();
 // capa superficial
 ctx.fillStyle='rgba(150,210,255,0.18)';ctx.fillRect(0,SY+4,870,80);
 // capa profunda fria
 const pf=A.p(tF-0.2,0.8,'softInOut');
 ctx.fillStyle='rgba(95,211,255,'+(0.22*pf)+')';ctx.fillRect(0,880,900,240);
 ctx.restore();
 // fondo marino y tierra
 A.lib.inkPath(ctx,floor,{width:5,color:A.pal.lineWhite,closed:true,fill:'#2a1d14',draw:A.p(0,1.4,'glide')});
 if(pin>0.5)A.lib.hatch(ctx,floor,{angle:0.8,spacing:16,width:1.5,color:'rgba(255,220,180,0.25)'});
 A.line([[0,SY],[870,SY]],{stroke:'#bfe6ff',lw:3,progress:A.p(0.2,1,'glide'),alpha:0.8});
 A.text('COSTA',985,500,{size:40,color:'#fff',weight:'800',align:'center',alpha:A.p(0.8,0.6)});
 // viento
 const pw=A.p(tV,0.6,'snapSettle');
 if(pw>0){
  for(let i=0;i<3;i++){const y=455+i*45;const off=((t-tV)*420+i*160)%520;
