  const g=ctx.createLinearGradient(0,SEA,0,1120);g.addColorStop(0,'#1c7f95');g.addColorStop(1,'#08303f');
  ctx.fillStyle=g;ctx.fillRect(0,SEA,620,1120-SEA);
  const wv=[];for(let x=0;x<=620;x+=20)wv.push([x,SEA+Math.sin(x*0.03+t*3)*5]);
  A.line(wv,{stroke:'#bff4fb',lw:4});
  A.lib.hatch(ctx,[[0,SEA+20],[600,SEA+20],[600,1120],[0,1120]],{angle:-0.6,spacing:22,width:1.5,color:'rgba(190,240,250,0.25)'});
  A.text('MAR FRÍO',300,1040,{size:46,color:'#e8fbff',weight:'900'});
},{alpha:p0});
// tierra
const land=[[560,1120],[560,905],[610,870],[650,790],[720,765],[800,780],[870,745],[960,765],[1080,755],[1080,1120]];
A.with(()=>{
  A.lib.inkPath(ctx,land,{width:4,color:'#e8f1f7',closed:true,fill:'#16222c'});
  A.lib.hatch(ctx,land,{angle:0.7,spacing:20,width:1.5,color:'rgba(255,183,77,0.22)'});
},{alpha:p0});
// burbuja que no sube
const pb=A.p(kPor,0.7,'bounceHard'), bf=1-A.p(kCasi+0.2,0.4,'softInOut');
if(pb>0&&bf>0){
  const up=A.p(kPor,0.35,'whip'), down=A.p(kPor+0.35,0.5,'bounceHard');
  const y=A.lerp(860,LID+40,up)+A.lerp(0,70,down);
  A.circle(470,y,32,{fill:'rgba(77,208,225,0.5)',stroke:'#fff',lw:3,alpha:bf});
  if(up>0.95) A.rings(470,LID,kPor+0.33,{count:2,maxR:90,color:'#fff',lw:3,alpha:0.7*bf});
}
// nube con lluvia tachada
const pn=A.pop(kCasi,0.45), cutP=A.p(kLl,0.35,'crashIn'), nf=1-A.p(kLl+0.6,0.5,'accelExit');
if(pn>0&&nf>0){
  A.with(()=>{
    if(cutP<1){for(let i=0;i<7;i++){const x=760+i*25, yy=600+((t*500+i*47)%110);A.line([[x,yy],[x-6,yy+24]],{stroke:'#9fe9f3',lw:4,alpha:1-cutP});}}
    [[780,560,42],[830,540,55],[880,565,40],[830,575,40]].forEach(c=>A.circle(c[0],c[1],c[2],{fill:'#d9e4ea'}));
  },{x:830,y:560,scale:pn*(1-0.4*(1-nf)),alpha:nf,shake:cutP>0&&cutP<1?10:0});
  if(cutP>0){A.line([[740,480],[920,660]],{stroke:warm,lw:14,progress:cutP,alpha:nf});A.line([[920,480],[740,660]],{stroke:warm,lw:14,progress:A.p(kLl+0.12,0.3,'crashIn'),alpha:nf});}
}
// sol y desierto
const ps=A.pop(kNorte,0.5);
if(ps>0){A.with(()=>A.sun(980,500,48),{x:980,y:500,scale:ps});
  A.label('NORTE: DESIERTO',840,960,{size:40,bg:warm,color:'#1a1206',scale:A.pop(kNorte+0.15,0.45)});}
// camanchaca
const pf=A.p(kApa-0.15,1.1,'glide');
if(pf>0){
  const front=A.lerp(-150,1180,pf);
  A.particles(46,7,(i,r)=>{
    const x=-120+i*28+r()*30+Math.sin(t*0.8+i)*12, y=LID+30+r()*70+(x>600?Math.max(0,60-(x-600)*0.2):0);
    if(x<front){ctx.fillStyle='rgba(235,248,252,0.20)';ctx.beginPath();ctx.arc(x,y,45+r()*45,0,Math.PI*2);ctx.fill();}
  });
}
// zona secundaria
const s1=A.p(kEn,0.5)*(1-A.p(kCasi,0.3,'softInOut'));
if(s1>0)A.text('MAR FRÍO → AIRE FRÍO',540,1500,{size:62,color:'#fff',weight:'900',alpha:s1});
const s2=A.p(kLl,0.4)*(1-A.p(kApa,0.3,'softInOut'));
if(s2>0)A.text('NO SUBE: NO LLUEVE',540,1500,{size:66,color:warm,weight:'900',alpha:s2});
const kc=kCam-0.2;
if(t>kc){
  A.label('CAMANCHACA',540,1480,{size:100,bg:ac,color:'#04202a',scale:A.pop(kc,0.5)});
  A.rings(540,1480,kc,{count:3,maxR:420,color:ac,lw:4,alpha:0.5});
  A.text('niebla costera',540,1620,{size:46,color:'#e8fbff',weight:'700',alpha:A.p(kc+0.15,0.4)});
}

const W=A.W, acc=A.accent, CY='#5fe3ff';
A.bg('#06142b','#020812');
const tG=A.k('grites',2.0), tE=A.k('entrar',2.667), tGr=A.k('gracias',4.0), tF=A.k('frío',5.0), tC=A.k('comes',5.333), tM=A.k('mariscos',6.333);
const SURF=780;
const SHX=[340,540,740];
const tS=4.5;
const shake = t>tE && t<tE+0.5 ? (1-(t-tE)/0.5)*14 : 0;
A.with(()=>{
  // arena
  ctx.fillStyle='#3a2f1c';
  ctx.beginPath(); ctx.moveTo(0,772); ctx.lineTo(300,790); ctx.lineTo(540,1120); ctx.lineTo(0,1120); ctx.closePath(); ctx.fill();
  A.lib.hatch(ctx, [[0,772],[300,790],[540,1120],[0,1120]], {angle:0.6, spacing:22, width:2, color:'rgba(255,212,0,0.18)'});
  // persona: empieza de pie en la orilla, camina y se hunde
  const px = A.lerp(190, 600, A.p(0.1,2.5,'glide'));
  const fy = A.lerp(772, 930, A.p(1.9,0.9,'softInOut'));
  const shiver = t>tE ? Math.sin(t*70)*5 : 0;
  const cold = A.p(tE,0.5,'softInOut');
  A.person(px+shiver, fy, {scale:1.5, color: cold>0.5 ? CY : '#ffffff'});
  // agua
  const g=ctx.createLinearGradient(0,SURF,0,1120);
  g.addColorStop(0,'rgba(20,120,190,0.88)'); g.addColorStop(1,'rgba(4,30,70,0.97)');
  ctx.fillStyle=g; ctx.beginPath(); ctx.moveTo(0,1120);
  for(let x=0;x<=W;x+=20){ ctx.lineTo(x, SURF+Math.sin(x*0.02+t*3)*8); }
  ctx.lineTo(W,1120); ctx.closePath(); ctx.fill();
  A.line(Array.from({length:55},(_,i)=>[i*20, SURF+Math.sin(i*20*0.02+t*3)*8]), {stroke:'#bff4ff', lw:4, alpha:0.8});
  // salpicadura
  if(t>tE){
    A.rings(px, SURF, tE, {count:3, speed:420, gap:60, maxR:240, color:'#bff4ff', lw:5});
    A.particles(16, 7, (i,r)=>{
      const dt=t-tE; if(dt>1.1) return;
      const a=-Math.PI*(0.15+0.7*r()), v=500+400*r();
      const x=px+Math.cos(a)*v*dt, y=SURF+Math.sin(a)*v*dt+900*dt*dt;
      if(y<SURF+10 && y>400) A.drop(x,y,10+8*r(),{fill:'#bff4ff'});
    });
  }
  // grito
  if(t>tG){
    const sc=A.pop(tG,0.45), sh=Math.sin(t*55)*6*(t<tE+0.6?1:0.3);
    const fade=1-A.p(tGr,0.5,'accelExit')*0.7;
    A.rings(px+60, 560, tG, {count:3, speed:300, gap:50, maxR:180, color:acc, lw:4, alpha:0.7*fade});
    A.with(()=>A.text('¡AAAH!', 780+sh, 500, {size:90, color:acc, weight:900, align:'center', stroke:'#000', strokeWidth:9}), {x:780, y:500, scale:sc, rot:-0.08, alpha:fade});
  }
  // temperatura
  if(t>tE+0.15){
    A.label('14°C', 880, 820, {size:72, bg:CY, color:'#03142b', scale:A.pop(tE+0.15,0.45)});
  }
  // surgencia
  if(t>tGr){
    const pp=A.p(tGr,1.0,'glide');
    [[700,1110,640,880],[830,1110,800,880],[960,1110,960,880]].forEach((c,i)=>{
      A.arrow(c[0],c[1],c[2],c[3],{progress:A.p(tGr+i*0.12,0.9,'glide'), color:CY, lw:10, head:30});
    });
    const out=A.p(tC,0.9,'whip');
    A.particles(22, 11, (i,r)=>{
      const x0=620+r()*380, ph=r();
      let y=1100-((t-tGr)*260+ph*300)%300;
      let x=x0+Math.sin(t*3+i)*12;
      const d=A.clamp(out*1.4-ph*0.4);
      const tx=SHX[i%3], ty=1460;
      x=A.lerp(x,tx,d); y=A.lerp(y,ty,d);
      A.circle(x,y,9,{fill:acc, glow:14, alpha:pp*(1-A.p(tC+0.8,0.4,'softInOut'))});
    });
    if(t>tF) A.label('AGUA FRÍA', 820, 1080, {size:56, bg:CY, color:'#03142b', scale:A.pop(tF,0.45)});
  }
},{shake});
// flechas: del agua fría hacia los mariscos
if(t>tGr+0.3){
  const src=[[700,1120],[830,1120],[960,1120]];
  src.forEach((s,i)=>{
    const tx=SHX[i], ty=1370;
    const mx=(s[0]+tx)/2+60, my=1250;
    const pts=Array.from({length:21},(_,j)=>{const u=j/20; return [(1-u)*(1-u)*s[0]+2*u*(1-u)*mx+u*u*tx, (1-u)*(1-u)*s[1]+2*u*(1-u)*my+u*u*ty];});
    const pr=A.p(tGr+0.3+i*0.15,1.0,'glide');
    A.line(pts,{stroke:acc, lw:5, alpha:0.75, dash:[18,14], progress:pr});
    if(pr>0.95){ const a=pts[19], b=pts[20]; A.arrow(a[0],a[1],b[0],b[1],{progress:1,color:acc,lw:5,head:26}); }
  });
}
// mariscos
function shell(cx,cy,s){
  const bx=cx, by=cy+55*s, R=110*s, a0=Math.PI*1.12, a1=Math.PI*1.88;
  ctx.save();
  ctx.beginPath(); ctx.moveTo(bx,by); ctx.arc(bx,by,R,a0,a1); ctx.closePath();
  ctx.fillStyle='#ff9a3c'; ctx.shadowColor=acc; ctx.shadowBlur=25; ctx.fill(); ctx.shadowBlur=0;
  ctx.lineWidth=5*s; ctx.strokeStyle='#3a1a00'; ctx.stroke();
  for(let i=1;i<7;i++){ const a=A.lerp(a0,a1,i/7); ctx.beginPath(); ctx.moveTo(bx,by); ctx.lineTo(bx+Math.cos(a)*R,by+Math.sin(a)*R); ctx.stroke(); }
  ctx.fillStyle=acc; ctx.fillRect(bx-26*s,by-6*s,52*s,20*s); ctx.strokeRect(bx-26*s,by-6*s,52*s,20*s);
  ctx.restore();
}
SHX.forEach((x,i)=>{
  const st=tS+i*0.2; if(t<st) return;
  const pin=A.p(st,0.7,'snapSettle');
  const yOff=A.lerp(300,0,pin);
  const bob=Math.sin(t*4+i)*8*pin;
  const glowUp = t>tC ? 1+0.12*A.pop(tC+0.5+i*0.1,0.4)-0.12 : 1;
  A.with(()=>shell(x,1460+bob+yOff,1.1), {x, y:1500+yOff, scale:glowUp, alpha:A.clamp(pin*1.5), rot:Math.sin(t*3+i)*0.06});
});
if(t>tM){
  A.flash(tM,0.25,0.35);
  A.with(()=>A.text('MARISCOS', 540, 1690, {size:110, color:acc, weight:900, align:'center', stroke:'#000', strokeWidth:10}), {x:540, y:1660, scale:A.pop(tM,0.45)});
  A.particles(10, 3, (i,r)=>{
    const a=r()*6.28, d=(t-tM)*300*(0.6+r());
    A.circle(540+Math.cos(a)*(200+d), 1500+Math.sin(a)*(120+d*0.6), 6, {fill:'#fff', glow:12, alpha:A.clamp(1-(t-tM)/0.6)});
  });
}

const W=A.W, ac=A.accent, ICE='#7FE3FF';
A.bg('#06142a','#020814');
const kS=A.k('Síguenos',0), kEn=A.k('entender',0.667), kCh=A.k('Chile',1.667), kMu=A.k('mundo',2.667), kCu=A.k('¿Cuál',3.0), kPl=A.k('playa',4.0), kHe=A.k('helada',4.667), kCo=A.k('conoces',5.333);

// ---------- Botón Seguir ----------
const pDown=A.p(kCh-0.1,0.7,'whip');
const by=A.lerp(770,1620,pDown), bs=A.lerp(1.7,1.0,pDown);
if(t<kCh+0.2) A.rings(540,by,kS+0.8,{count:3,speed:520,gap:0.18,maxR:420,color:ac,lw:5,alpha:1-pDown});
A.with(()=>A.follow(540,by,kS,kS+0.8),{x:540,y:by,scale:bs*A.pop(kS,0.5)});
// etiqueta entender
const pEnOut=A.p(kCh-0.15,0.35,'accelExit');
if(t>=kEn && pEnOut<1) A.label('ENTENDER',540,560,{size:70,bg:ac,color:'#06142a',scale:A.pop(kEn,0.45),alpha:1-pEnOut});

// ---------- Franja de Chile ----------
const offX=A.lerp(0,-150,A.p(kCu,0.7,'glide'));
const N=40, coast=[], andes=[];
for(let i=0;i<=N;i++){
  const y=450+i*16.25;
  const x=560-i*1.6+10*Math.sin(i*1.3)+6*Math.sin(i*3.1)+offX;
  coast.push([x,y]);
  andes.push([x+46-i*0.55+4*Math.sin(i*2.2),y]);
}
const pc=A.p(kCh,0.8,'softLand');
// globo detrás
const pg=A.p(kMu,0.6,'snapSettle'), pgo=A.p(kCu,0.5,'accelExit');
if(t>=kMu && pgo<1){
  const ga=1-pgo, r=330*pg*(1+0.15*pgo);
  A.circle(540,775,r,{stroke:A.pal.paleBlue||'#9cc8ff',lw:5,alpha:ga,glow:12});
  ctx.save(); ctx.globalAlpha=ga*0.55; ctx.strokeStyle=A.pal.paleBlue||'#9cc8ff'; ctx.lineWidth=2.5;
  for(let m=0;m<6;m++){
    const ph=((m/6)+t*0.12)%1, rx=Math.abs(Math.cos(ph*Math.PI))*r;
    ctx.beginPath(); ctx.ellipse(540,775,Math.max(rx,0.5),r,0,0,Math.PI*2); ctx.stroke();
  }
  for(let l=-2;l<=2;l++){
    const yy=775+l*r*0.38, rr=Math.sqrt(Math.max(0,r*r-(l*r*0.38)**2));
    ctx.beginPath(); ctx.ellipse(540,yy,rr,rr*0.12,0,0,Math.PI*2); ctx.stroke();
  }
  ctx.restore();
  A.label('EL MUNDO',540,1095,{size:58,bg:A.pal.paleBlue||'#9cc8ff',color:'#06142a',scale:A.pop(kMu,0.45),alpha:ga});
}
if(t>=kCh){
  const poly=coast.concat(andes.slice().reverse());
  ctx.save(); ctx.globalAlpha=pc;
  ctx.fillStyle='rgba(255,212,0,0.12)'; ctx.beginPath();
  poly.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1])); ctx.closePath(); ctx.fill();
  A.lib.hatch(ctx,poly,{angle:0.8,spacing:11,width:1.6,color:'rgba(255,212,0,0.45)'});
  ctx.restore();
  A.line(coast,{stroke:ac,lw:6,progress:pc});
  A.line(andes,{stroke:ac,lw:3,progress:pc,alpha:0.7});
  const chA=1-A.p(kMu-0.1,0.3,'softInOut')*0.0;
  A.label('CHILE',coast[8][0]+210,coast[8][1],{size:60,bg:ac,color:'#06142a',scale:A.pop(kCh+0.2,0.45),alpha:chA*(1-A.p(kPl-0.2,0.3,'softInOut'))});
}

// ---------- Termómetro ----------
const pT=A.p(kCu+0.1,0.6,'snapSettle');
const pH=A.p(kHe,0.8,'crashIn');
const shake=t>kHe&&t<kHe+0.4?10*(1-(t-kHe)/0.4):0;
if(t>=kCu){
  A.with(()=>{
    const tx=820, top=500, bot=1000;
    const col=pH>0.5?ICE:ac;
    A.rect(tx-38,top,76,bot-top,{r:38,stroke:'#ffffff',lw:5,fill:'rgba(255,255,255,0.06)'});
    A.circle(tx,bot+30,62,{stroke:'#ffffff',lw:5,fill:col,glow:20});
    const lvl=A.lerp(0.85,0.25,pH)+0.01*Math.sin(t*8);
    const ly=bot-(bot-top-30)*lvl;
    A.rect(tx-20,ly,40,bot-ly+20,{r:20,fill:col});
    for(let g=0;g<6;g++) A.line([[tx+38,top+40+g*75],[tx+60,top+40+g*75]],{stroke:'#ffffff',lw:3,alpha:0.7});
    A.text(A.counter(24,12,pH,0)+'°',tx,top-40,{size:92,color:col,weight:900,align:'center',stroke:'#06142a',strokeWidth:8});
  },{x:820,y:770,scale:pT,alpha:pT,shake});
}

// ---------- Playas ----------
const beaches=[[8,'18°'],[20,'15°'],[32,'12°']];
beaches.forEach((b,j)=>{
  const st=kPl+j*0.13; if(t<st) return;
  const p=coast[b[0]], s=A.pop(st,0.45);
  const cold=j===2;
  const col=cold&&pH>0.5?ICE:'#ffffff';
  if(cold&&t>=kHe) A.rings(p[0],p[1],kHe,{count:3,speed:260,gap:0.25,maxR:170,color:ICE,lw:4});
  A.with(()=>{
    A.line([[p[0],p[1]],[p[0]-70,p[1]-60]],{stroke:col,lw:4});
    A.drop(p[0]-70,p[1]-80,26,{fill:cold&&pH>0.5?ICE:'#4fa3ff',stroke:'#ffffff'});
    A.circle(p[0],p[1],10,{fill:col});
    A.text(b[1],p[0]-120,p[1]-65,{size:52,color:col,weight:800,align:'right'});
  },{x:p[0],y:p[1],scale:s});
});

// escarcha
if(t>=kHe){
  const fa=A.p(kHe,0.4,'softInOut');
  A.particles(26,7,(i,rnd)=>{
    const x=rnd()*W, sp=60+rnd()*90, y=420+((rnd()*700+(t-kHe)*sp)%700);
    A.circle(x,y,2+rnd()*4,{fill:ICE,alpha:fa*0.7});
  });
}

// ---------- Pregunta final ----------
if(t>=kCo){
  const s=A.pop(kCo,0.5);
  A.with(()=>{
    A.rect(320,1380,440,130,{r:36,fill:ac,glow:20});
    ctx.fillStyle=ac; ctx.beginPath(); ctx.moveTo(500,1508); ctx.lineTo(560,1508); ctx.lineTo(520,1550); ctx.closePath(); ctx.fill();
    A.text('¿TU PLAYA?',540,1468,{size:66,color:'#06142a',weight:900,align:'center'});
  },{x:540,y:1500,scale:s});
}
A.flash(kHe,0.25,0.25);
